const {chromium}=require(process.env.PLAYWRIGHT_MODULE || '@playwright/test');
const assert=require('node:assert/strict');
const fs=require('node:fs/promises');
(async()=>{
 const browser=await chromium.launch({executablePath:process.env.CHROME_PATH,headless:true});
 const name='Native history fixture '+Date.now();const errors=[];
 const context=await browser.newContext({viewport:{width:1440,height:1000},acceptDownloads:true});
 context.setDefaultTimeout(180000);const page=await context.newPage();page.on('pageerror',e=>errors.push(e.message));
 await page.goto('http://localhost:8099/__fixture/login',{waitUntil:'domcontentloaded'});
 await page.getByRole('button',{name:'Chat',exact:true}).click();
 await page.locator('textarea').fill(name);await page.locator('textarea').press('Enter');
 const checkCard=async(p)=>{
  await p.getByText('native-history-result',{exact:true}).waitFor({timeout:90000});
  assert.match(await p.getByRole('link',{name:'View Product',exact:true}).getAttribute('href'),/^\/admin\/catalog\/products\/edit\/\d+$/);
  const waiting=p.waitForEvent('download');await p.getByRole('button',{name:'Download',exact:true}).click();
  const download=await waiting;assert.match(await fs.readFile(await download.path(),'utf8'),/EXTENSION-FIXTURE,Native export/);
 };
 await checkCard(page);
 await page.getByRole('button',{name:'No',exact:true}).click();
 await page.getByText('Cancelled the native fixture request.',{exact:true}).waitFor({timeout:90000});
 await page.getByRole('button',{name:/^Sessions/}).click();
 await page.locator('.ap-session-card').filter({hasText:name}).click();await checkCard(page);
 const all=await (await context.request.get('http://localhost:8099/admin/ai-agent/conversations')).json();
 const conversation=all.conversations.find(c=>c.title===name);assert.ok(conversation);
 const saved=await (await context.request.get('http://localhost:8099/admin/ai-agent/conversations/'+conversation.id)).json();
 const result=saved.messages.find(m=>m.result?.marker==='native-history-result');
 assert.equal(result._confirmed,true);assert.equal(result.action,'agent_response');
 await page.reload({waitUntil:"domcontentloaded"});await checkCard(page);
 await page.screenshot({path:'native-history-light.png'});
 console.log('PASS native result card, product link, actual download and confirmed state survive session reopening/reload');
 const fresh=await browser.newContext({viewport:{width:1440,height:1000},acceptDownloads:true});fresh.setDefaultTimeout(180000);const p=await fresh.newPage();p.on('pageerror',e=>errors.push(e.message));
 await p.goto('http://localhost:8099/__fixture/login',{waitUntil:'domcontentloaded'});
 assert.equal(await p.getByText('native-history-result',{exact:true}).count(),0);
 await p.getByRole('button',{name:/^Sessions/}).click();
 await p.locator('.ap-session-card').filter({hasText:name}).click();await checkCard(p);
 assert.equal(await p.getByRole('button',{name:'No',exact:true}).count(),0);
 await fresh.addCookies([{name:'dark_mode',value:'dark',url:'http://localhost:8099'}]);await p.reload({waitUntil:"domcontentloaded"});await checkCard(p);
 await p.screenshot({path:'native-history-dark.png'});
 console.log('PASS second browser with empty chat storage restores native display from database, light/dark');
 assert.deepEqual(errors,[]);await browser.close();
})().catch(e=>{console.error(e);process.exit(1)});
